import type { Hex } from "viem";

/**
 * Frozen known-answer vectors for ERC-5564 scheme 1.
 *
 * ERC-5564 ships no hex test vectors of its own, so these were produced by running ScopeLift's
 * `stealth-address-sdk` — the implementation the ecosystem built against — over fixed inputs, and
 * every value here was generated by that SDK rather than by the code under test. The inputs are a
 * keccak chain from a published label, so they are reproducible and obviously not cherry-picked.
 *
 * `reference.test.ts` checks us against that SDK live. This file does the same job without it: if
 * the dev dependency is ever dropped or drifts, these still pin the exact bytes. Never regenerate
 * them from our own output — that would turn a compatibility test into a snapshot of whatever we
 * happen to do today.
 */

export type StealthVector = {
  spendingPrivateKey: Hex;
  viewingPrivateKey: Hex;
  spendingPublicKey: Hex;
  viewingPublicKey: Hex;
  metaAddress: Hex;
  ephemeralPrivateKey: Hex;
  ephemeralPublicKey: Hex;
  viewTag: Hex;
  stealthAddress: Hex;
  stealthPrivateKey: Hex;
};

