/**
 * Signature-to-keys vectors.
 *
 * Unlike the vectors above, this derivation is Ghost Pay's own — ERC-5564 says nothing about where
 * the two keypairs come from, and ScopeLift's SDK splits the signature into halves where we hash it
 * into a seed with domain separators (see `keys.ts`). Nothing on-chain depends on the choice; what
 * depends on it is every existing user's ability to recover their keys. These vectors exist to make
 * an accidental change to that derivation fail loudly instead of silently orphaning funds.
 */
export type KeyVector = {
  signature: Hex;
  spendingPrivateKey: Hex;
  spendingPublicKey: Hex;
  viewingPrivateKey: Hex;
  viewingPublicKey: Hex;
};

